su = html.match(/method=\\"get\\" action=\\"(.+?)\\"/)[1];
s = html.match(/name=\\"s\\" value=\\"(.+?)\\"/)[1];
body = 's=' + key + '&act=hztopy';
py = java.post('http://m.maifeizx.com/pinyin.html', body, head).body();
py = JSON.parse(py);
key = py.data;
java.log(py);
'http://m.maifeizx.com' + su + '?ie=gbk&s=' + s + '&q=' + key;

