function getUrl(_) {
  const { java, source } =_|| this
  let v = String(source.getVariable())
  if(v.length < 1){
    source.setVariable("8")
    v = v.match(/^\d+$/) ? v : 0
  }
  return urls[v]
}

function getIndex(a){
	let i=urls.indexOf(a)+1
	return i
	}

